'use strict';
// Audit only: every hosted SQL request is a READ ONLY transaction ending in ROLLBACK.
// No gameplay, sync, equip, claim or rollout function is invoked.
const fs=require('node:fs'),path=require('node:path'),crypto=require('node:crypto');
const c=require('E:/Proyectos/Aventura-de-Palabras-i18n-stage2b/tools/rewards-categories-deployment/common.cjs');
const root=path.resolve(__dirname,'..'),out=path.join(root,'.local-developer/tower-rewards-audit-20261106');fs.mkdirSync(out,{recursive:true});
const snapshot=c.readOnly(`select jsonb_build_object(
 'readOnly',current_setting('transaction_read_only'),'databaseVersion',version(),
 'rollout',(select jsonb_build_object('enabled',enabled,'paymentsEnabled',payments_enabled,'globalEnabled',global_enabled,'pilotCount',cardinality(pilot_users),'onlyPreviouslyApprovedOwner',pilot_users=array['e9dc89b5-1d6b-4f2b-a31b-fe3bd7673a20'::uuid]) from versus_private.tower_rollout),
 'migrations',(select jsonb_agg(jsonb_build_object('version',version,'name',name) order by version) from supabase_migrations.schema_migrations where name ilike '%tower%' or name ilike '%arcade%'),
 'counts',jsonb_build_object('accounts',(select count(*) from auth.users),'wallets',(select count(*) from versus_private.game_wallets),'walletCoins',(select sum(coins) from versus_private.game_wallets),'definitions',(select count(*) from versus_private.tower_definitions),'attempts',(select count(*) from versus_private.tower_attempts),'verifiedFloors',(select count(*) from versus_private.tower_verified_floors),'progressRows',(select count(*) from versus_private.tower_progress),'completedCharacters',(select count(*) from versus_private.tower_progress where completed=10),'coinReceipts',(select count(*) from versus_private.tower_coin_receipts),'towerCoins',(select coalesce(sum(amount),0) from versus_private.tower_coin_receipts)),
 'attemptStatuses',(select coalesce(jsonb_object_agg(status,n),'{}') from (select status,count(*) n from versus_private.tower_attempts group by status) q),
 'definitions',(select jsonb_agg(to_jsonb(t) order by character_key,floor) from versus_private.tower_definitions t),
 'progressByCharacter',(select coalesce(jsonb_agg(to_jsonb(t) order by character_key),'[]') from (select character_key,count(*) accounts,max(completed) max_completed,sum(completed) total_completed from versus_private.tower_progress group by character_key) t),
 'integrity',jsonb_build_object('invalidVerifiedEvidence',(select count(*) from versus_private.tower_verified_floors v join versus_private.tower_attempts a on a.id=v.attempt_id join versus_private.tower_definitions d on d.key=a.definition where a.user_id<>v.user_id or a.status<>'won' or d.character_key<>v.character_key or d.floor<>v.floor),'invalidCoinAmounts',(select count(*) from versus_private.tower_coin_receipts where amount<>case when floor<=4 then 30 when floor<=9 then 50 else 150 end),'progressWithoutCompleteProof',(select count(*) from versus_private.tower_progress p where p.completed>0 and p.completed<>(select count(*) from versus_private.tower_verified_floors v where v.user_id=p.user_id and v.character_key=p.character_key and v.floor<=p.completed))),
 'towerTables',(select jsonb_agg(jsonb_build_object('name',t.relname,'rls',t.relrowsecurity,'anonAccess',has_table_privilege('anon',t.oid,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE'),'authenticatedAccess',has_table_privilege('authenticated',t.oid,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE')) order by t.relname) from pg_class t join pg_namespace n on n.oid=t.relnamespace where n.nspname='versus_private' and t.relname like 'tower_%' and t.relkind='r'),
 'constraints',(select jsonb_agg(jsonb_build_object('table',conrelid::regclass::text,'name',conname,'definition',pg_get_constraintdef(oid)) order by conname) from pg_constraint where connamespace='versus_private'::regnamespace and (conrelid::regclass::text like '%tower_%' or conname in ('player_appearance_frame_key_check','versus_players_frame_key_check'))),
 'indexes',(select jsonb_agg(jsonb_build_object('name',indexname,'definition',indexdef) order by indexname) from pg_indexes where schemaname='versus_private' and tablename like 'tower_%'),
 'towerItemsInWallet',(select count(*) from versus_private.game_wallets w where exists(select 1 from unnest(w.owned) x where x like 'tower_%' or x like 'tower-%')),
 'towerFramesInXPCatalog',(select count(*) from versus_private.xp_rewards where frame like 'tower_%'),
 'towerFramesEquipped',(select count(*) from versus_private.player_appearance where frame_key like 'tower_%'),
 'relevantFunctions',(select jsonb_agg(jsonb_build_object('signature',p.oid::regprocedure::text,'definer',p.prosecdef,'settings',p.proconfig,'anonExecute',has_function_privilege('anon',p.oid,'EXECUTE'),'authExecute',has_function_privilege('authenticated',p.oid,'EXECUTE'),'sha256',encode(extensions.digest(pg_get_functiondef(p.oid),'sha256'),'hex')) order by p.oid::regprocedure::text) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('public','versus_private') and p.prokind='f' and (p.proname like 'tower_%' or p.proname ~ '(wallet|appearance|profile|cosmetic|costume|frame)')),
 'fingerprints',jsonb_build_object('wallets',${c.fingerprint('versus_private.game_wallets')},'characters',${c.fingerprint('versus_private.character_inventory')},'xpCosmetics',${c.fingerprint('versus_private.xp_cosmetics')},'towerProgress',${c.fingerprint('versus_private.tower_progress')},'towerVerified',${c.fingerprint('versus_private.tower_verified_floors')},'towerReceipts',${c.fingerprint('versus_private.tower_coin_receipts')})
) audit`)[0].audit;
const functions=c.readOnly(`select p.oid::regprocedure::text signature,pg_get_functiondef(p.oid) definition from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('public','versus_private') and p.prokind='f' and (p.proname like 'tower_%' or p.proname ~ '(wallet|appearance|profile|cosmetic|costume|frame)') order by 1`);
fs.writeFileSync(path.join(out,'functions.json'),JSON.stringify(functions,null,2));
const report={checkedAt:new Date().toISOString(),project:c.project,productionWrites:0,rpcInvocations:0,migrationsInstalled:0,...snapshot};
fs.writeFileSync(path.join(root,'docs/tower-rewards-audit-20261106.json'),JSON.stringify(report,null,2));
console.log(JSON.stringify({checkedAt:report.checkedAt,readOnly:report.readOnly,rollout:report.rollout,counts:report.counts,attemptStatuses:report.attemptStatuses,progressByCharacter:report.progressByCharacter,integrity:report.integrity,towerItemsInWallet:report.towerItemsInWallet,towerFramesInXPCatalog:report.towerFramesInXPCatalog,towerFramesEquipped:report.towerFramesEquipped,functions:functions.map(f=>f.signature),tables:report.towerTables},null,2));
